from pathlib import Path
import json
import pandas as pd
ROOT=Path(__file__).resolve().parent.parent
REPORTS=ROOT/'reports'; REPORTS.mkdir(exist_ok=True)
def find(paths):
    for p in paths:
        if p.exists(): return p
    raise FileNotFoundError('Arquivo não encontrado. Procurei: '+', '.join(map(str,paths)))
def main():
    sf=find([ROOT/'data/processed/fact_sales.csv',ROOT/'data/analytics/fact_sales.csv',ROOT/'data/fact_sales.csv'])
    pf=find([ROOT/'data/raw/olist_order_payments_dataset.csv',ROOT/'data/processed/olist_order_payments_dataset.csv',ROOT/'data/olist_order_payments_dataset.csv'])
    s=pd.read_csv(sf); p=pd.read_csv(pf)
    s['order_purchase_timestamp']=pd.to_datetime(s.order_purchase_timestamp,errors='coerce')
    s['purchase_year_month']=s.order_purchase_timestamp.dt.to_period('M').astype(str)
    s['product_category_name']=s.product_category_name.fillna('Sem categoria').astype(str)
    s['category_label']=s.product_category_name.str.replace('_',' ',regex=False).str.title()
    # Payment information summarized per order; payment totals are not duplicated in item-level revenue.
    po=p.groupby('order_id').agg(payment_value=('payment_value','sum'),payment_type=('payment_type',lambda z:z.mode().iat[0] if not z.mode().empty else 'not_defined')).reset_index()
    s=s.merge(po,on='order_id',how='left')
    cols=['order_id','purchase_year_month','customer_state','product_category_name','category_label','item_revenue','customer_unique_id','payment_type','payment_value']
    data=json.dumps(s[cols].where(pd.notna(s[cols]),None).to_dict('records'),ensure_ascii=False,separators=(',',':'))
    html='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Brazilian E-commerce | Analytics</title><script src="https://cdn.plot.ly/plotly-2.35.2.min.js"></script><style>
:root{--bg:#080b16;--panel:#171e32;--text:#f8fafc;--muted:#9aabc8;--pink:#e879a7;--purple:#8b7cf6;--border:#293149}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,"Segoe UI",Arial}header{padding:12px 20px;background:#0e1222;display:flex;justify-content:space-between;align-items:center}h1{font-size:25px;margin:0;font-weight:800}.sub{color:var(--muted);margin-top:4px;font-size:12px}main{padding:8px 14px;max-width:1900px;margin:auto}.sect{font-size:9px;letter-spacing:1.8px;color:#a5b4fc;font-weight:800;margin:7px 0 5px;text-transform:uppercase}.filters{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr)) auto;gap:8px;margin:5px 0 9px}select,button{background:#202941;color:#e8edff;border:1px solid #39435e;border-radius:8px;padding:9px 10px;min-width:0}button{cursor:pointer;background:#382541;border-color:#875078}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.kpi,.panel{background:linear-gradient(145deg,#1b2238,#151b2c);border:1px solid var(--border);border-radius:13px;min-width:0}.kpi{padding:9px 13px}.label{font-size:11px;color:var(--muted)}.value{font-size:clamp(19px,2vw,27px);font-weight:800;margin-top:7px}.panel{padding:3px;overflow:hidden}.wide{margin-bottom:5px}.top{display:grid;grid-template-columns:1.15fr .85fr;gap:6px}.bottom{display:grid;grid-template-columns:minmax(320px,.42fr) 1fr;gap:6px}.plot{width:100%;height:190px}.monthly{height:155px}.payment{height:260px}.brand{display:flex;align-items:center;gap:14px}.logo{width:50px;height:50px;border-radius:15px;background:linear-gradient(135deg,#e879a7,#8b7cf6);display:grid;place-items:center;font-size:25px;font-weight:900;color:white}.notes{height:260px;padding:13px 15px;display:flex;flex-direction:column;gap:9px}.note-title{font-size:14px;font-weight:600;color:#f8fafc}.notes textarea{flex:1;resize:none;background:#111827;border:1px solid #303951;border-radius:9px;color:#e5e7eb;padding:12px;font:13px Inter,Arial;outline:none}.notes textarea:focus{border-color:#8b7cf6}.note-foot{font-size:10px;color:#7786a5}footer{text-align:center;color:#66748f;font-size:10px;padding:8px}@media(max-width:850px){.filters{grid-template-columns:repeat(2,1fr)}.kpis{grid-template-columns:repeat(2,1fr)}.top,.bottom{grid-template-columns:1fr}}
</style></head><body><header><div class="brand"><div class="logo">B</div><div><h1>Brazilian E-commerce</h1><div class="sub">Business Intelligence · Analytics Overview</div></div></div><span style="color:#f9a8d4">● DATA ANALYTICS</span></header><main>
<div class="sect">Filtros de análise</div><div class="filters"><select id="period"><option value="">Todo o período</option></select><select id="state"><option value="">Todos os estados</option></select><select id="category"><option value="">Todas as categorias</option></select><select id="payment"><option value="">Todos os pagamentos</option></select><button id="reset">Limpar filtros</button></div>
<div class="sect">Visão geral do negócio</div><section class="kpis"><div class="kpi"><div class="label">Receita de produtos</div><div class="value" id="revenue">—</div></div><div class="kpi"><div class="label">Pedidos</div><div class="value" id="orders">—</div></div><div class="kpi"><div class="label">Ticket médio</div><div class="value" id="ticket">—</div></div><div class="kpi"><div class="label">Clientes únicos</div><div class="value" id="customers">—</div></div></section>
<div class="sect">01 — Evolução e sazonalidade</div><section class="panel wide"><div id="monthly" class="plot monthly"></div></section><div class="sect">02 — Onde a receita acontece</div><section class="top"><div class="panel"><div id="categories" class="plot"></div></div><div class="panel"><div id="states" class="plot"></div></div></section><div class="sect">03 — Comportamento de compra</div><section class="bottom"><div class="panel"><div id="payments" class="plot payment"></div></div><div class="panel"><div class="notes"><div class="note-title">Anotações da análise</div><textarea id="notes" placeholder="Registre insights, hipóteses ou pontos para investigar..."></textarea><div class="note-foot">As anotações ficam salvas neste navegador.</div></div></div></section><footer>BRAZILIAN E-COMMERCE · ANALYTICS EXPERIENCE · OLIST DATASET</footer></main>
<script>const DATA=__DATA__;const $=id=>document.getElementById(id),fmt=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),num=n=>n.toLocaleString('pt-BR'),nice=s=>String(s||'Sem categoria').replaceAll('_',' ').replace(/\\b\\w/g,c=>c.toUpperCase());
function fill(id,vals){vals.sort().forEach(v=>{let o=document.createElement('option');o.value=v;o.textContent=nice(v);$(id).appendChild(o)})}fill('period',[...new Set(DATA.map(x=>x.purchase_year_month))]);fill('state',[...new Set(DATA.map(x=>x.customer_state).filter(Boolean))]);fill('category',[...new Set(DATA.map(x=>x.product_category_name))]);fill('payment',[...new Set(DATA.map(x=>x.payment_type).filter(Boolean))]);
const base={paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{color:'#cbd5e1',size:10},margin:{l:45,r:15,t:38,b:28},title:{font:{size:13,color:'#f8fafc'},x:.04},xaxis:{gridcolor:'rgba(148,163,184,.08)'},yaxis:{gridcolor:'rgba(148,163,184,0)'}};function draw(id,tr,l){
const merged={...base,...l,
 xaxis:{...base.xaxis,...(l.xaxis||{}),gridcolor:'rgba(148,163,184,.08)',zerolinecolor:'rgba(148,163,184,.12)'},
 yaxis:{...base.yaxis,...(l.yaxis||{}),gridcolor:'rgba(148,163,184,0)',zerolinecolor:'rgba(148,163,184,.12)'}
};
Plotly.react(id,tr,merged,{responsive:true,displayModeBar:false})
}
function update(){let a=$('period').value,b=$('state').value,c=$('category').value,e=$('payment').value;let d=DATA.filter(x=>(!a||x.purchase_year_month===a)&&(!b||x.customer_state===b)&&(!c||x.product_category_name===c)&&(!e||x.payment_type===e));let rev=d.reduce((z,x)=>z+(+x.item_revenue||0),0),ord=new Set(d.map(x=>x.order_id)),cus=new Set(d.map(x=>x.customer_unique_id));$('revenue').textContent=fmt(rev);$('orders').textContent=num(ord.size);$('ticket').textContent=fmt(ord.size?rev/ord.size:0);$('customers').textContent=num(cus.size);
let m={},cat={},st={};d.forEach(x=>{m[x.purchase_year_month]=(m[x.purchase_year_month]||0)+(+x.item_revenue||0);cat[x.category_label]=(cat[x.category_label]||0)+(+x.item_revenue||0);st[x.customer_state]=(st[x.customer_state]||0)+(+x.item_revenue||0)});let mk=Object.keys(m).sort();draw('monthly',[{x:mk,y:mk.map(k=>m[k]),type:'scatter',mode:'lines',line:{color:'#e879a7',width:3},fill:'tozeroy',fillcolor:'rgba(232,121,167,.16)',hovertemplate:'%{x}<br>R$ %{y:,.2f}<extra></extra>'}],{title:'Evolução mensal da receita',xaxis:{title:'Mês'},yaxis:{title:'Receita (R$)'}});
let cc=Object.entries(cat).sort((x,y)=>y[1]-x[1]).slice(0,10).reverse();draw('categories',[{x:cc.map(x=>x[1]),y:cc.map(x=>x[0]),type:'bar',orientation:'h',marker:{color:'#e879a7'},hovertemplate:'<b>%{y}</b><br>Receita: R$ %{x:,.2f}<extra></extra>'}],{title:'Categorias com maior receita',xaxis:{title:'Receita (R$)'},yaxis:{automargin:true}});let ss=Object.entries(st).sort((x,y)=>y[1]-x[1]).slice(0,10).reverse();draw('states',[{x:ss.map(x=>x[1]),y:ss.map(x=>x[0]),type:'bar',orientation:'h',marker:{color:'#8b7cf6'},hovertemplate:'Estado %{y}<br>R$ %{x:,.2f}<extra></extra>'}],{title:'Estados com maior receita',xaxis:{title:'Receita (R$)'},yaxis:{automargin:true}});
let pays={},seenPay={};d.forEach(x=>{if(!seenPay[x.order_id]){seenPay[x.order_id]=1;let k=nice(x.payment_type);pays[k]=(pays[k]||0)+(+x.payment_value||0)}});draw('payments',[{labels:Object.keys(pays),values:Object.values(pays),type:'pie',hole:.62,textinfo:'percent',textposition:'inside',marker:{colors:['#8b7cf6','#e879a7','#38bdf8','#fbbf24','#34d399']}}],{title:'Participação dos pagamentos',showlegend:true,legend:{orientation:'v'}});
}
['period','state','category','payment'].forEach(id=>$(id).addEventListener('change',update));$('reset').onclick=()=>{['period','state','category','payment'].forEach(id=>$(id).value='');update()};update();
const note=$('notes');note.value=localStorage.getItem('olist-dashboard-notes')||'';note.addEventListener('input',()=>localStorage.setItem('olist-dashboard-notes',note.value));
</script></body></html>'''